// Learnify — tests: questionnaires and assessments, plus the AI queue.
// Routes: `/tests`, `/tests/{kind}/{id}`, `/tests/{kind}/{id}/edit`, `/drafts`
//
// `kind` is `q` (questionnaire — practice with a deadline) or `a` (assessment
// — the formal subject-wise exam that auto-issues a certificate on a pass).
// Both containers expose the same endpoints, so every helper below just maps
// `kind` onto `/v1/questionnaires` or `/v1/assessments`.
//
// Taking a test happens in player.js (`#/take/{kind}/{id}`) — we only link
// there. Nothing authored by a trainer or generated by AI ever reaches a
// trainee without a Supreme release, and every piece of server text goes
// through `esc()` on its way into HTML.

import { api, esc, toast } from './utils.js?v=62';
import * as ui from './ui.js?v=62';
import { go, confirmAction, currentUser, openAppModal, closeAppModal } from './app.js?v=62';
import { iconSvg } from './icons.js?v=62';

// ─── Shared bits ────────────────────────────────────────────────────────────

// Filters survive a re-render within the route but reset when you leave.
const filters = { kind: 'q', q: '', subject: '', status: '', mine: false };
const draftFilters = { kind: '', status: 'DRAFT' };
let debounce = 0;
let subjectsCache = null;

const baseFor = (kind) => (kind === 'a' ? 'assessments' : 'questionnaires');
const normKind = (k) => (k === 'a' ? 'a' : 'q');
const kindWord = (kind, cap = false) => {
  const w = kind === 'a' ? 'assessment' : 'questionnaire';
  return cap ? w.charAt(0).toUpperCase() + w.slice(1) : w;
};
const isAuthor = (u) => !!u && (u.role === 'MASTER' || u.role === 'SUPREME');
const isSupreme = (u) => !!u && u.role === 'SUPREME';

const DIFF_TONE = { easy: 'ok', medium: 'info', hard: 'warn' };
function diffTag(d) {
  const v = String(d || 'medium');
  return ui.tone(v.charAt(0).toUpperCase() + v.slice(1), DIFF_TONE[v] || 'mute');
}

/** Question rows sorted the way the paper should read. */
function orderedQuestions(rows) {
  return (rows || []).slice()
    .sort((a, b) => (Number(a.sort_order) || 0) - (Number(b.sort_order) || 0));
}
function orderedOptions(q) {
  return (q.options || []).slice()
    .sort((a, b) => (Number(a.sort_order) || 0) - (Number(b.sort_order) || 0));
}

/** All subjects with their curated topic lists (cached for the session). */
async function loadSubjects() {
  if (subjectsCache) return subjectsCache;
  try {
    const res = await api('/v1/subjects/with-topics');
    subjectsCache = ui.data(res) || [];
  } catch (_) {
    return [];
  }
  return subjectsCache;
}

function topicNames(subjects) {
  const map = {};
  (subjects || []).forEach((s) => (s.topics || []).forEach((t) => {
    map[t.id] = t.name;
  }));
  return map;
}

/** Full PUT body for either container, built from the row we already hold. */
function testPayload(kind, test, patch) {
  const t = Object.assign({}, test, patch);
  if (kind === 'q') {
    return {
      title: t.title, description: t.description || '',
      subject_id: t.subject_id || '', topic_id: t.topic_id || '',
      course_id: t.course_id || '', deadline_at: t.deadline_at || '',
      duration_minutes: Number(t.duration_minutes) || 30,
      max_attempts: Number(t.max_attempts) || 1,
    };
  }
  return {
    title: t.title, description: t.description || '',
    subject_id: t.subject_id || '', course_id: t.course_id || '',
    deadline_at: t.deadline_at || '',
    duration_minutes: Number(t.duration_minutes) || 30,
    max_score: Number(t.max_score) || 100,
    passing_score: Number(t.passing_score) || 60,
  };
}

function toLocalInput(iso) {
  if (!iso) return '';
  const d = new Date(iso);
  if (isNaN(d)) return '';
  const p = (n) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}T${
    p(d.getHours())}:${p(d.getMinutes())}`;
}

function elapsedLabel(sec) {
  const s = Math.max(0, Number(sec) || 0);
  const m = Math.floor(s / 60);
  if (m >= 60) return `${Math.floor(m / 60)}h ${m % 60}m`;
  return `${m}m ${s % 60}s`;
}

/** `GET /v1/ai/status` -> {configured, model, features:{question_generation}} */
function aiEnabled(res) {
  const d = ui.data(res);
  if (d && typeof d === 'object') {
    if (typeof d.configured === 'boolean') return d.configured;
    const f = d.features && d.features.question_generation;
    if (typeof f === 'boolean') return f;
    return true;
  }
  return !!d;
}

// ─── /tests — the catalogue ─────────────────────────────────────────────────

export async function list(root, ctx) {
  const user = currentUser();
  const canAuthor = isAuthor(user);
  if (!canAuthor) { filters.status = ''; filters.mine = false; }

  const offs = [];
  root.innerHTML = ui.head({
    title: 'Tests',
    sub: canAuthor
      ? 'Questionnaires are practice with a deadline; assessments are the formal exam that issues a certificate on a pass.'
      : 'Practice with a deadline, or the formal exam that earns you a certificate — pick a test and begin.',
    actions: canAuthor
      ? `<button class="btn ghost sm" data-new="q">+ New questionnaire</button>
         <button class="btn primary sm" data-new="a">+ New assessment</button>`
      : '',
  })
    + `<div class="seg" data-kind-seg>
         <button type="button" class="seg-btn${filters.kind === 'q' ? ' active' : ''}"
                 data-kind="q">Questionnaires</button>
         <button type="button" class="seg-btn${filters.kind === 'a' ? ' active' : ''}"
                 data-kind="a">Assessments</button>
       </div>`
    + '<div data-body>' + ui.loading('tests') + '</div>';

  const body = root.querySelector('[data-body]');

  offs.push(ui.click(root, '[data-new]', (e, btn) => createTest(btn.dataset.new, btn)));
  offs.push(ui.click(root, '[data-kind]', (e, btn) => {
    filters.kind = normKind(btn.dataset.kind);
    root.querySelectorAll('[data-kind]').forEach((b) =>
      b.classList.toggle('active', b.dataset.kind === filters.kind));
    load(body, canAuthor);
  }));
  offs.push(ui.click(root, '[data-retry]', (e, a) => { e.preventDefault(); load(body, canAuthor); }));

  // Subject filter options come from the catalogue, not hardcoded.
  let subjects = [];
  try {
    const res = await api('/v1/subjects?limit=200');
    subjects = ui.data(res) || [];
  } catch (_) { subjects = []; }

  renderToolbar(root, subjects, canAuthor, body);
  load(body, canAuthor);

  return { destroy() { offs.forEach((o) => o()); clearTimeout(debounce); } };
}

function renderToolbar(root, subjects, canAuthor, body) {
  const bar = document.createElement('div');
  bar.className = 'toolbar';
  bar.innerHTML = `
    <div class="grow"><input type="search" name="q" placeholder="Search tests…"
      value="${esc(filters.q)}" aria-label="Search tests"></div>
    <select name="subject" aria-label="Filter by subject">
      <option value="">All subjects</option>
      ${subjects.map((s) => `<option value="${esc(s.id)}"${
        filters.subject === s.id ? ' selected' : ''}>${esc(s.name)}</option>`).join('')}
    </select>
    ${canAuthor ? `
      <select name="status" aria-label="Filter by status">
        <option value="">Any status</option>
        ${['DRAFT', 'PENDING_RELEASE', 'PUBLISHED', 'ENDED', 'ARCHIVED']
          .map((s) => `<option value="${s}"${
            filters.status === s ? ' selected' : ''}>${s.replace(/_/g, ' ')
              .replace(/\b\w/g, (c) => c.toUpperCase())}</option>`).join('')}
      </select>
      <button class="btn ghost sm${filters.mine ? ' active' : ''}" data-mine>Mine only</button>` : ''}
    <button class="btn primary sm" data-apply>Apply</button>`;

  root.insertBefore(bar, body);

  const apply = (toggleMine) => {
    filters.q = bar.querySelector('[name=q]').value.trim();
    filters.subject = bar.querySelector('[name=subject]').value;
    const st = bar.querySelector('[name=status]');
    if (st) filters.status = st.value;
    const mine = bar.querySelector('[data-mine]');
    if (mine && toggleMine) filters.mine = !filters.mine;
    if (mine) mine.classList.toggle('active', filters.mine);
    load(body, canAuthor);
  };

  ui.click(bar, '[data-apply]', () => apply(false));
  ui.click(bar, '[data-mine]', () => apply(true));
  bar.querySelector('[name=q]').addEventListener('input', () => {
    clearTimeout(debounce);
    debounce = setTimeout(() => apply(false), 320);
  });
  bar.querySelector('[name=subject]').addEventListener('change', () => apply(false));
  const st = bar.querySelector('[name=status]');
  if (st) st.addEventListener('change', () => apply(false));
}

async function load(target, canAuthor) {
  const kind = filters.kind;
  target.innerHTML = ui.loading(kind === 'q' ? 'questionnaires' : 'assessments');
  try {
    const params = new URLSearchParams();
    if (filters.q) params.set('q', filters.q);
    if (filters.subject) params.set('subject_id', filters.subject);
    if (filters.status) params.set('status', filters.status);
    if (filters.mine) params.set('mine', 'true');
    params.set('limit', '120');

    const res = await api(`/v1/${baseFor(kind)}?${params.toString()}`);
    const rows = ui.data(res) || [];
    target.innerHTML = rows.length
      ? renderRows(kind, rows, canAuthor)
      : ui.blank({
          title: `No ${kind === 'q' ? 'questionnaires' : 'assessments'} match`,
          body: 'Try clearing the search or choosing a different subject.',
          action: filters.q || filters.subject || filters.status
            ? 'Clear filters' : '',
          actionHref: '#/tests',
        });
  } catch (err) {
    target.innerHTML = ui.errorBlock(err.message);
  }
}

function renderRows(kind, rows, canAuthor) {
  const cols = [
    { label: 'Test', get: (r) => `<a class="link" href="#/tests/${kind}/${esc(r.id)}">${
      esc(r.title)}</a>${!canAuthor && r.trainer_name
        ? `<br><span class="sm dim">${esc(r.trainer_name)}</span>` : ''}` },
    { label: 'Subject', get: (r) => esc(r.subject_name || 'Unassigned') },
    { label: 'Status', get: (r) => ui.tag(r.status) },
    { label: 'Questions', get: (r) => esc(String(r.question_count ?? 0)) },
  ];
  if (!canAuthor) cols.push({ label: 'Attempts', get: (r) => attemptsCell(kind, r) });
  cols.push({ label: 'Deadline', get: (r) => deadlineCell(r) });
  cols.push({ label: 'Action', get: (r) => actionCell(kind, r, canAuthor) });

  return ui.table(cols, rows, 'id')
    + `<p class="muted sm center mt">${rows.length} ${
      kind === 'q' ? 'questionnaire' : 'assessment'}${rows.length === 1 ? '' : 's'} shown</p>`;
}

function attemptsCell(kind, r) {
  const live = r.has_live ? ' <span class="tag info">In progress</span>' : '';
  if (kind === 'a') {
    const n = (r.my_attempts || []).length;
    return `${esc(String(n))} of 1${live}`;
  }
  return `${esc(String(r.attempts_used || 0))} of ${esc(String(r.max_attempts || 1))}${live}`;
}

function deadlineCell(r) {
  if (!r.deadline_at) return '<span class="dim">No deadline</span>';
  return `<span class="sm">${esc(ui.fmtDate(r.deadline_at, { withTime: true, short: true }))}</span>
          <br><span class="sm muted">${esc(ui.countdown(r.deadline_at))}</span>`;
}

function actionCell(kind, r, canAuthor) {
  if (canAuthor) return `<a class="btn ghost sm" href="#/tests/${kind}/${esc(r.id)}">Open</a>`;
  return `<a class="btn primary sm" href="#/take/${kind}/${esc(r.id)}">Take</a>`;
}

async function createTest(kind, btn) {
  const title = kind === 'a' ? 'Untitled assessment' : 'Untitled questionnaire';
  await ui.busy(btn, 'Creating…', async () => {
    try {
      const res = await api(`/v1/${baseFor(kind)}`, {
        method: 'POST',
        body: JSON.stringify({ title }),
      });
      const row = ui.data(res);
      if (!row || !row.id) throw new Error(`The ${kindWord(kind)} could not be created.`);
      toast('Draft created — add your questions next.');
      go(`/tests/${kind}/${row.id}/edit`);
    } catch (err) {
      toast(err.message, 'warn');
    }
  });
}

// ─── /tests/{kind}/{id} — the paper ─────────────────────────────────────────

export async function detail(root, ctx) {
  const kind = normKind(ctx.params.kind);
  const id = ctx.params.id;
  const user = currentUser();
  const base = baseFor(kind);
  const offs = [];
  root.innerHTML = ui.loading('test');

  let test = null;
  let questions = [];
  let subjects = [];
  let attempts = [];
  let live = null;

  try {
    const author = isAuthor(user);
    const [tRes, qRes, sRes, aRes, lRes] = await Promise.all([
      api(`/v1/${base}/${id}`),
      author
        ? api(`/v1/${base}/${id}/questions`)
        : Promise.resolve([]),
      loadSubjects(),
      author
        ? api(`/v1/${base}/${id}/attempts?limit=100`).catch(() => [])
        : api(`/v1/${base}/${id}/attempts/mine`).catch(() => []),
      kind === 'a' && author
        ? api(`/v1/${base}/${id}/live`).catch(() => null)
        : Promise.resolve(null),
    ]);
    test = ui.data(tRes);
    questions = orderedQuestions(ui.data(qRes) || []);
    subjects = sRes || [];
    attempts = ui.data(aRes) || [];
    live = lRes ? (ui.data(lRes) || []) : null;
    if (!test) throw new Error('Test not found.');
  } catch (err) {
    root.innerHTML = ui.head({ title: 'Test' })
      + ui.blank({ title: 'Test unavailable', body: esc(err.message) });
    return { destroy() { offs.forEach((o) => o()); } };
  }

  const canEdit = isAuthor(user) && !!test.can_edit;
  const alpha = !!user && user.role === 'ALPHA';
  const tnames = topicNames(subjects);

  let course = null;
  if (test.course_id) {
    try { course = ui.data(await api('/v1/courses/' + test.course_id)); }
    catch (_) { course = null; }
  }

  const actions = [];
  if (canEdit) {
    actions.push(`<a class="btn ghost sm" href="#/tests/${kind}/${esc(id)}/edit">Edit questions</a>`);
  } else if (alpha && test.status === 'PUBLISHED' && !test.overdue) {
    actions.push(`<a class="btn primary sm" href="#/take/${kind}/${esc(id)}">${
      test.has_live ? 'Resume test' : 'Take test'}</a>`);
  }

  const meta = [
    ['Subject', test.subject_name || 'Unassigned'],
    ['Topic', test.topic_id ? (tnames[test.topic_id] || 'Tagged topic') : ''],
    ['Course', course ? course.title : ''],
    ['Duration', `${Number(test.duration_minutes) || 0} min`],
    ['Deadline', test.deadline_at
      ? ui.fmtDate(test.deadline_at, { withTime: true }) : 'No deadline'],
    kind === 'a' ? ['Maximum score', String(test.max_score ?? 100)] : null,
    kind === 'a' ? ['Passing score', String(test.passing_score ?? 60)] : null,
    kind === 'q' ? ['Attempts allowed', String(test.max_attempts ?? 1)] : null,
    ['Trainer', test.trainer_name || '—'],
  ].filter(Boolean);

  const qCount = questions.length || Number(test.question_count ?? 0);

  root.innerHTML = `
    <div class="crumbs"><a href="#/tests">&larr; All tests</a></div>
    ${ui.head({
      title: test.title,
      sub: `${kindWord(kind, true)}${
        test.subject_name ? ' · ' + esc(test.subject_name) : ''}${
        kind === 'a' ? ' · certificate on a pass' : ''}`,
      actions: actions.join(''),
    })}

    <div class="wrap mb">
      ${ui.tag(test.status)}
      <span class="tag ${kind === 'a' ? 'info' : 'mute'}">${kind === 'a'
        ? 'Formal exam' : 'Practice test'}</span>
      <span class="tag mute">${qCount} question${
        qCount === 1 ? '' : 's'}</span>
      ${test.deadline_at ? `<span class="tag ${test.overdue ? 'mute' : 'warn'}">${
        esc(ui.countdown(test.deadline_at))}</span>` : ''}
      ${test.has_live ? '<span class="tag info">Attempt in progress</span>' : ''}
    </div>

    ${test.description
      ? `<div class="card mb"><p class="page-sub" style="margin:0">${
        esc(test.description)}</p></div>` : ''}

    <div class="two-col wide-left">
      <div class="stack">
        ${canEdit
          ? `<div class="card" data-qlist>${
              questionsInner(questions, tnames, kind, id)}</div>`
          : `<div class="card">
              <div class="card-head"><h3>About this paper</h3></div>
              ${ui.note('The paper opens when you start the test — questions, options and ' +
                'explanations stay hidden until you submit.')}
             </div>`}

        <div class="card" data-att>${attemptsInner(attempts, kind, canEdit)}</div>

        ${kind === 'a' && canEdit
          ? `<div class="card" data-live>${liveInner(live || [])}</div>` : ''}
      </div>

      <div class="stack">
        <div class="card">
          <div class="card-head"><h3>Details</h3></div>
          ${ui.kv(meta)}
          ${test.course_id
            ? `<p class="sm mt"><a class="link" href="#/courses/${esc(test.course_id)}">Open linked course</a></p>`
            : ''}
        </div>

        ${canEdit
          ? `<div class="card">
               <div class="card-head"><h3>Release</h3></div>
               ${releasePanel(kind, test, user)}
             </div>` : ''}
      </div>
    </div>`;

  // ── pieces that reload in place ──────────────────────────────────────────
  const reloadQuestions = async () => {
    const box = root.querySelector('[data-qlist]');
    if (!box) return;
    try {
      const res = await api(`/v1/${base}/${id}/questions`);
      questions = orderedQuestions(ui.data(res) || []);
      box.innerHTML = questionsInner(questions, tnames, kind, id);
    } catch (err) { box.innerHTML = ui.errorBlock(err.message); }
  };

  const reloadAttempts = async () => {
    const box = root.querySelector('[data-att]');
    if (!box) return;
    try {
      const res = await api(canEdit
        ? `/v1/${base}/${id}/attempts?limit=100`
        : `/v1/${base}/${id}/attempts/mine`);
      attempts = ui.data(res) || [];
      box.innerHTML = attemptsInner(attempts, kind, canEdit);
    } catch (err) { box.innerHTML = ui.errorBlock(err.message); }
  };

  const reloadLive = async () => {
    const box = root.querySelector('[data-live]');
    if (!box) return;
    box.innerHTML = ui.loading('live attempts');
    try {
      const res = await api(`/v1/${base}/${id}/live`);
      live = ui.data(res) || [];
      box.innerHTML = liveInner(live);
    } catch (err) { box.innerHTML = ui.errorBlock(err.message); }
  };

  // ── bindings ─────────────────────────────────────────────────────────────
  offs.push(ui.click(root, '[data-retry]', (e) => {
    e.preventDefault();
    go(`/tests/${kind}/${id}`);
  }));

  offs.push(ui.click(root, '[data-move]', async (e, btn) => {
    const ids = questions.map((q) => q.id);
    const at = ids.indexOf(btn.dataset.qid);
    const to = btn.dataset.move === 'up' ? at - 1 : at + 1;
    if (at < 0 || to < 0 || to >= ids.length) return;
    [ids[at], ids[to]] = [ids[to], ids[at]];
    btn.disabled = true;
    try {
      await api(`/v1/${base}/${id}/questions-order`, {
        method: 'PUT', body: JSON.stringify({ order: ids }),
      });
      await reloadQuestions();
    } catch (err) {
      toast(err.message, 'warn');
      btn.disabled = false;
    }
  }));

  offs.push(ui.click(root, '[data-del-q]', async (e, btn) => {
    const ok = await confirmAction('Delete this question?',
      'It leaves the paper straight away — trainees lose it on their next load.',
      'Delete');
    if (!ok) return;
    try {
      await api(`/v1/${base}/${id}/questions/${btn.dataset.delQ}`, { method: 'DELETE' });
      toast('Question deleted.');
      await reloadQuestions();
    } catch (err) { toast(err.message, 'warn'); }
  }));

  offs.push(ui.click(root, '[data-void]', async (e, btn) => {
    const ok = await confirmAction('Void this attempt?',
      'The attempt is excluded from all results and any certificate earned from it is revoked.',
      'Void attempt');
    if (!ok) return;
    try {
      await api(`/v1/${base}/${id}/attempts/${btn.dataset.void}/void`, {
        method: 'POST', body: '{}',
      });
      toast('Attempt voided.');
      await reloadAttempts();
      if (kind === 'a') await reloadLive();
    } catch (err) { toast(err.message, 'warn'); }
  }));

  offs.push(ui.click(root, '[data-live-refresh]', () => reloadLive()));

  offs.push(ui.click(root, '[data-life]', async (e, btn) => {
    const act = btn.dataset.life;
    let body = '{}';
    if (act === 'reject') {
      const ok = await confirmAction('Send this back?',
        'The trainer can edit it and submit it again for release.', 'Send back');
      if (!ok) return;
    } else if (act === 'end') {
      const ok = await confirmAction('End this test now?',
        'The window closes and everyone still sitting is submitted straight away.',
        'End now');
      if (!ok) return;
    } else if (act === 'reopen') {
      const dl = await promptDeadline(test.deadline_at);
      if (dl === null) return;
      body = dl ? JSON.stringify({ deadline_at: dl }) : '{}';
    }
    await ui.busy(btn, 'Working…', async () => {
      try {
        await api(`/v1/${base}/${id}/${act}`, { method: 'POST', body });
        toast({
          submit: 'Sent to Supreme for release.',
          release: 'Released — trainees can take it now.',
          reject: 'Sent back to the trainer.',
          end: 'Test ended and everyone still sitting was submitted.',
          reopen: 'The test is open again.',
        }[act] || 'Done.');
        go(`/tests/${kind}/${id}`);
      } catch (err) { toast(err.message, 'warn'); }
    });
  }));

  return { destroy() { offs.forEach((o) => o()); } };
}

function questionsInner(questions, tnames, kind, id) {
  const head = `<div class="card-head"><h3>Questions</h3>
    <span class="sm muted">${questions.length} on this paper</span></div>`;
  if (!questions.length) {
    return head + ui.blank({
      title: 'No questions yet',
      body: 'Add one by hand or generate a batch with AI — nothing is visible to ' +
        'trainees until the test is released.',
      action: 'Add the first question',
      actionHref: `#/tests/${kind}/${id}/edit`,
    });
  }
  return head + `<div class="stack">${questions
    .map((q, i) => questionCard(q, i, tnames, kind, id, questions.length))
    .join('')}</div>`;
}

function questionCard(q, i, tnames, kind, id, total) {
  const opts = orderedOptions(q);
  return `
    <div class="q-card">
      <div class="q-head">
        <span class="q-n">${i + 1}</span>
        <div class="q-tags">
          ${diffTag(q.difficulty)}
          ${q.topic_id
            ? `<span class="tag info">${esc(tnames[q.topic_id] || 'Tagged topic')}</span>`
            : '<span class="tag warn">No topic</span>'}
          <span class="tag mute">${esc(String(q.points ?? 1))} pt</span>
        </div>
        <span class="grow"></span>
        <div class="q-acts">
          <button type="button" class="btn ghost sm" data-move="up" data-qid="${esc(q.id)}"
            aria-label="Move up" title="Move up"${i === 0 ? ' disabled' : ''}>&uarr;</button>
          <button type="button" class="btn ghost sm" data-move="down" data-qid="${esc(q.id)}"
            aria-label="Move down" title="Move down"${i === total - 1 ? ' disabled' : ''}>&darr;</button>
          <a class="btn ghost sm" href="#/tests/${kind}/${esc(id)}/edit">Edit</a>
          <button type="button" class="btn ghost sm" data-del-q="${esc(q.id)}">Delete</button>
        </div>
      </div>
      <p class="q-text">${esc(q.text)}</p>
      <ul class="q-opts">
        ${opts.map((o) => `<li class="q-opt${o.is_correct ? ' ok' : ''}">
          <span class="q-mark">${o.is_correct ? iconSvg('check') : ''}</span>
          <span>${esc(o.text)}</span>
          ${o.is_correct ? '<span class="tag ok">Correct</span>' : ''}
        </li>`).join('')}
      </ul>
      ${q.explanation ? `<p class="q-why">Explanation: ${esc(q.explanation)}</p>` : ''}
    </div>`;
}

function attemptsInner(rows, kind, canEdit) {
  const head = `<div class="card-head"><h3>${canEdit ? 'Attempts' : 'Your attempts'}</h3>
    <span class="sm muted">${rows.length}</span></div>`;
  if (!rows.length) {
    return head + '<div class="empty-state">No attempts recorded yet.</div>';
  }
  if (!canEdit) {
    const cols = [
      { label: 'Attempt', get: (r) => `#${esc(String(r.attempt_no || 1))}` },
      { label: 'Submitted', get: (r) => esc(ui.relTime(r.submitted_at || r.started_at)) },
      { label: 'Score', get: (r) => `${esc(String(r.score ?? 0))} / ${esc(String(r.max_score ?? 0))}` },
      { label: 'Result', get: (r) => resultCell(kind, r) },
      { label: 'Status', get: (r) => ui.tag(r.status) },
    ];
    return head + ui.table(cols, rows, 'id');
  }

  const cols = [
    { label: 'Trainee', get: (r) => `<b>${esc(r.name || 'Trainee')}</b>${
      r.email ? `<br><span class="sm dim">${esc(r.email)}</span>` : ''}` },
    { label: 'Attempt', get: (r) => `#${esc(String(r.attempt_no || 1))}` },
    { label: 'Submitted', get: (r) => esc(ui.relTime(r.submitted_at || r.started_at)) },
    { label: 'Score', get: (r) => `${esc(String(r.score ?? 0))} / ${esc(String(r.max_score ?? 0))}` },
    { label: 'Result', get: (r) => resultCell(kind, r) },
    { label: 'Status', get: (r) => ui.tag(r.status) },
    { label: 'Action', get: (r) => r.status === 'VOIDED'
        ? '<span class="sm dim">Voided</span>'
        : `<button type="button" class="btn ghost sm" data-void="${esc(r.id)}">Void</button>` },
  ];
  return head + ui.table(cols, rows, 'id');
}

function resultCell(kind, r) {
  if (kind === 'a' && typeof r.passed === 'boolean') {
    return r.passed ? ui.tone('Passed', 'ok') : ui.tone('Failed', 'bad');
  }
  if (r.percentage === undefined || r.percentage === null) return '<span class="dim">—</span>';
  return `<span class="sm">${esc(ui.pct(r.percentage))}</span>`;
}

function liveInner(rows) {
  const head = `<div class="card-head"><h3>Sitting right now</h3>
    <span class="sm muted">${rows.length} in progress</span>
    <span class="grow"></span>
    <button type="button" class="btn ghost sm" data-live-refresh>Refresh</button></div>`;
  if (!rows.length) {
    return head + '<div class="empty-state">Nobody is mid-attempt.</div>';
  }
  return head + `<div class="live-list">${rows.map((r) => `
    <div class="live-row">
      <b>${esc(r.name || 'Trainee')}</b>
      <span class="sm dim">${esc(r.department || r.email || '')}</span>
      <span class="grow"></span>
      <span class="sm muted">started ${esc(ui.relTime(r.started_at))}</span>
      <span class="tag info">${esc(elapsedLabel(r.elapsed_seconds))} in</span>
    </div>`).join('')}</div>`;
}

function releasePanel(kind, test, user) {
  const supreme = isSupreme(user);
  const href = `#/tests/${kind}/${esc(test.id)}/edit`;
  const s = test.status;

  if (s === 'DRAFT' || s === 'REJECTED') {
    return ui.note(s === 'REJECTED'
      ? '<b>Changes requested.</b><br>Supreme sent this back. Fix the questions, then submit it again.'
      : '<b>Still a draft.</b><br>Add questions, then send it to Supreme for release.')
      + `<div class="row gap mt">
           <a class="btn primary sm" href="${href}">Add question</a>
           <a class="btn ghost sm" href="${href}">Generate with AI</a>
         </div>
         <div class="mt"><button type="button" class="btn primary sm"
           data-life="submit">Submit for release</button></div>`;
  }

  if (s === 'PENDING_RELEASE') {
    return ui.note(supreme
      ? '<b>Waiting on you.</b><br>This test is in the release queue — approve it or send it back.'
      : '<b>Waiting on Supreme.</b><br>This test is in the release queue. You will be notified either way.',
      'warn')
      + (supreme
        ? `<div class="row gap mt">
             <button type="button" class="btn primary sm" data-life="release">Release</button>
             <button type="button" class="btn ghost sm" data-life="reject">Reject</button>
           </div>` : '');
  }

  if (s === 'PUBLISHED') {
    return ui.note(kind === 'a'
      ? '<b>Live on the portal.</b><br>Trainees can sit this exam — passing issues a certificate automatically.'
      : '<b>Live on the portal.</b><br>Trainees can attempt this practice test until the deadline.')
      + (supreme
        ? `<div class="row gap mt">
             <button type="button" class="btn ghost sm" data-life="end">End now</button>
             <button type="button" class="btn ghost sm" data-life="reopen">Reopen deadline</button>
           </div>` : '');
  }

  if (s === 'ENDED') {
    return ui.note('<b>Closed.</b><br>The window has shut and everyone still sitting was submitted.')
      + (supreme
        ? `<div class="mt"><button type="button" class="btn primary sm"
             data-life="reopen">Reopen test</button></div>` : '');
  }

  return ui.note('<b>Archived.</b><br>This test is out of circulation.', 'warn')
    + (supreme
      ? `<div class="mt"><button type="button" class="btn primary sm"
           data-life="reopen">Reopen test</button></div>` : '');
}

/** Optional new deadline for a reopen. Resolves `null` on cancel. */
function promptDeadline(current) {
  return new Promise((resolve) => {
    openAppModal(`
      <h3 class="modal-title">Reopen deadline</h3>
      <p class="modal-sub">Pick a new deadline, or leave it empty to reopen with no deadline.</p>
      <form data-reopen-form>
        <div class="field"><label>New deadline</label>
          <input type="datetime-local" name="deadline_at" value="${esc(toLocalInput(current))}"></div>
        <div class="row gap" style="margin-top:14px;justify-content:flex-end">
          <button type="button" class="btn ghost sm" data-reopen-cancel>Cancel</button>
          <button type="submit" class="btn primary sm">Reopen</button>
        </div>
      </form>`);
    const host = document.getElementById('app-modal-body');
    const form = host ? host.querySelector('[data-reopen-form]') : null;
    if (!form) { resolve(null); return; }
    const done = (v) => { closeAppModal(); resolve(v); };
    form.querySelector('[data-reopen-cancel]')
      .addEventListener('click', () => done(null));
    form.addEventListener('submit', (e) => {
      e.preventDefault();
      const v = form.querySelector('[name=deadline_at]').value;
      done(v ? new Date(v).toISOString() : '');
    });
  });
}

// ─── /tests/{kind}/{id}/edit — authoring ────────────────────────────────────

export async function edit(root, ctx) {
  const kind = normKind(ctx.params.kind);
  const id = ctx.params.id;
  const base = baseFor(kind);
  const offs = [];
  root.innerHTML = ui.loading('authoring');

  let test = null;
  let questions = [];
  let subjects = [];
  let aiOk = false;

  try {
    const [tRes, sRes, aiRes] = await Promise.all([
      api(`/v1/${base}/${id}`),
      loadSubjects(),
      api('/v1/ai/status').catch(() => true),
    ]);
    test = ui.data(tRes);
    subjects = sRes || [];
    aiOk = aiEnabled(aiRes);
    if (!test) throw new Error('Test not found.');
    if (!test.can_edit) throw new Error('You do not own this test.');
    const qRes = await api(`/v1/${base}/${id}/questions`);
    questions = orderedQuestions(ui.data(qRes) || []);
  } catch (err) {
    root.innerHTML = ui.head({ title: 'Authoring' })
      + ui.blank({ title: 'Cannot edit this test', body: esc(err.message) });
    return { destroy() { offs.forEach((o) => o()); } };
  }

  const subject = subjects.find((s) => s.id === test.subject_id) || null;
  const topics = subject ? (subject.topics || []) : [];
  const tnames = topicNames(subjects);
  const released = ['PUBLISHED', 'ENDED', 'ARCHIVED'].includes(test.status);

  root.innerHTML = `
    <div class="crumbs"><a href="#/tests/${kind}/${esc(id)}">&larr; ${
      esc(test.title)}</a></div>
    ${ui.head({
      title: 'Add questions',
      sub: `${kindWord(kind, true)} · ${
        test.subject_name ? esc(test.subject_name) : 'no subject yet'} · ${
        questions.length} question${questions.length === 1 ? '' : 's'} so far`,
    })}

    ${released ? ui.note(
      'This test has been released. Supreme needs to re-open it before changes ' +
      'reach trainees — you can keep drafting here.', 'warn') : ''}

    ${subject ? '' : subjectPicker(subjects)}

    <div class="two-col wide-left mt">
      <div class="stack">
        ${subject ? authorForm(kind, topics) : ''}
        <div class="card" data-qlist>${mineInner(questions, tnames)}</div>
      </div>
      <div class="stack">
        ${aiCard(topics, subjects, aiOk, test)}
        <div class="card">
          <div class="card-head"><h3>This ${kindWord(kind)}</h3>${ui.tag(test.status)}</div>
          ${ui.kv([
            ['Title', test.title],
            ['Subject', test.subject_name || 'Unassigned'],
            ['Duration', `${Number(test.duration_minutes) || 0} min`],
            ['Deadline', test.deadline_at
              ? ui.fmtDate(test.deadline_at, { withTime: true }) : 'No deadline'],
            kind === 'a' ? ['Maximum score', String(test.max_score ?? 100)] : null,
            kind === 'a' ? ['Passing score', String(test.passing_score ?? 60)] : null,
            kind === 'q' ? ['Attempts allowed', String(test.max_attempts ?? 1)] : null,
          ].filter(Boolean))}
        </div>
      </div>
    </div>`;

  const reloadList = async () => {
    const box = root.querySelector('[data-qlist]');
    if (!box) return;
    try {
      const res = await api(`/v1/${base}/${id}/questions`);
      questions = orderedQuestions(ui.data(res) || []);
      box.innerHTML = mineInner(questions, tnames);
    } catch (err) { box.innerHTML = ui.errorBlock(err.message); }
  };

  // ── subject setup (only when the test has none yet) ──────────────────────
  offs.push(ui.on(root, '[data-subject-form]', 'submit', async (e) => {
    e.preventDefault();
    const form = e.target;
    const value = form.querySelector('[name=subject_id]').value;
    if (!value) { ui.formError(form, 'Choose the subject this test covers.'); return; }
    ui.formError(form, '');
    const btn = form.querySelector('[type=submit]');
    await ui.busy(btn, 'Saving…', async () => {
      try {
        await api(`/v1/${base}/${id}`, {
          method: 'PUT',
          body: JSON.stringify(testPayload(kind, test, { subject_id: value })),
        });
        toast('Subject set — now tag every question with a topic.');
        go(`/tests/${kind}/${id}/edit`);
      } catch (err) { ui.formError(form, err.message); }
    });
  }));

  // ── the single-question authoring form ───────────────────────────────────
  offs.push(ui.on(root, '[data-qform]', 'submit', async (e) => {
    e.preventDefault();
    const form = e.target;
    const text = form.querySelector('[name=text]').value.trim();
    const topicId = form.querySelector('[name=topic_id]').value;
    const difficulty = form.querySelector('[name=difficulty]').value;
    const explanation = form.querySelector('[name=explanation]').value.trim();
    const points = Number(form.querySelector('[name=points]').value) || 1;
    const inputs = Array.from(form.querySelectorAll('[name=opt]'));
    const values = inputs.map((i) => i.value.trim());
    const checked = form.querySelector('[name=correct]:checked');
    const correctAt = checked ? Number(checked.value) : 0;

    if (text.length < 3) {
      ui.formError(form, 'Write the question first — it needs at least 3 characters.');
      return;
    }
    if (!topicId) {
      ui.formError(form, 'Pick a topic tag. Every question needs one for the reports.');
      return;
    }
    const kept = values.map((t, i) => ({ t, i })).filter((o) => o.t);
    if (kept.length < 2) {
      ui.formError(form, 'Enter at least two options.');
      return;
    }
    if (!values[correctAt]) {
      ui.formError(form, 'The option marked correct is empty — fill it in or mark another.');
      return;
    }
    if (!(points > 0)) { ui.formError(form, 'Points must be greater than zero.'); return; }
    ui.formError(form, '');

    const btn = form.querySelector('[type=submit]');
    await ui.busy(btn, 'Saving…', async () => {
      try {
        await api(`/v1/${base}/${id}/questions`, {
          method: 'POST',
          body: JSON.stringify({
            text, explanation, difficulty, topic_id: topicId, points,
            options: kept.map((o) => ({
              text: o.t, is_correct: o.i === correctAt,
            })),
          }),
        });
        toast('Question added.');
        form.reset();
        await reloadList();
      } catch (err) { ui.formError(form, err.message); }
    });
  }));

  // ── AI drafting ──────────────────────────────────────────────────────────
  offs.push(ui.on(root, '[data-aiform] [name=subject_id]', 'change', async (e) => {
    const sid = e.target.value;
    const sel = root.querySelector('[data-aiform] [name=topic_id]');
    if (!sel) return;
    sel.innerHTML = '<option value="">All topics…</option>';
    if (!sid) return;
    try {
      const res = await api(`/v1/subjects/${sid}/topics`);
      const rows = ui.data(res) || [];
      sel.innerHTML = '<option value="">All topics…</option>'
        + rows.map((t) => `<option value="${esc(t.id)}">${esc(t.name)}</option>`).join('');
    } catch (_) { /* keep the "all topics" default */ }
  }));

  offs.push(ui.on(root, '[data-aiform]', 'submit', async (e) => {
    e.preventDefault();
    const form = e.target;
    const count = Number(form.querySelector('[name=count]').value) || 0;
    const subjectId = form.querySelector('[name=subject_id]').value;
    if (!subjectId) {
      ui.formError(form, 'Choose the subject to generate questions for.');
      return;
    }
    if (count < 1 || count > 40) {
      ui.formError(form, 'Ask for between 1 and 40 questions.');
      return;
    }
    ui.formError(form, '');
    const btn = form.querySelector('[type=submit]');
    await ui.busy(btn, 'Generating…', async () => {
      try {
        const res = await api('/v1/ai/generate-questions', {
          method: 'POST',
          body: JSON.stringify({
            subject_id: subjectId,
            topic_ids: form.querySelector('[name=topic_id]').value
              ? [form.querySelector('[name=topic_id]').value] : [],
            count,
            difficulty: form.querySelector('[name=difficulty]').value,
            kind: kind === 'a' ? 'ASSESSMENT' : 'QUESTIONNAIRE',
            context: form.querySelector('[name=context]').value.trim(),
          }),
        });
        const made = ui.data(res) || [];
        const out = root.querySelector('[data-airesult]');
        if (out) {
          out.innerHTML = ui.note(
            `<b>${made.length} draft${made.length === 1 ? '' : 's'} queued.</b><br>
             Nothing goes live on its own — review, edit and publish them from the
             <a class="link" href="#/drafts">draft queue</a>.`);
        }
        toast(`${made.length} draft${made.length === 1 ? '' : 's'} waiting in the queue.`);
        form.reset();
      } catch (err) { ui.formError(form, err.message); }
    });
  }));

  // ── remove a question from the list ──────────────────────────────────────
  offs.push(ui.click(root, '[data-del-q]', async (e, btn) => {
    const ok = await confirmAction('Delete this question?',
      'It leaves the paper straight away.', 'Delete');
    if (!ok) return;
    try {
      await api(`/v1/${base}/${id}/questions/${btn.dataset.delQ}`, { method: 'DELETE' });
      toast('Question deleted.');
      await reloadList();
    } catch (err) { toast(err.message, 'warn'); }
  }));

  offs.push(ui.click(root, '[data-retry]', (e) => {
    e.preventDefault();
    go(`/tests/${kind}/${id}/edit`);
  }));

  return { destroy() { offs.forEach((o) => o()); } };
}

function subjectPicker(subjects) {
  return `
    <div class="card">
      <div class="card-head"><h3>Choose a subject first</h3></div>
      <p class="sm muted" style="margin-top:0">Topics belong to a subject, and every
        question must carry a topic tag — so pick the subject this test covers.</p>
      <form data-subject-form>
        <div class="field"><label>Subject</label>
          <select name="subject_id">
            <option value="">Select a subject…</option>
            ${subjects.map((s) => `<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('')}
          </select></div>
        <div class="row gap" style="justify-content:flex-end">
          <span class="sm bad" data-err></span>
          <button type="submit" class="btn primary sm">Save subject</button>
        </div>
      </form>
    </div>`;
}

function authorForm(kind, topics) {
  return `
    <div class="card">
      <div class="card-head"><h3>New question</h3>
        <span class="sm muted">4 options, one correct</span></div>
      <form data-qform novalidate>
        <div class="field"><label>Question text</label>
          <textarea name="text" rows="3" placeholder="Which of these…"></textarea></div>

        <div class="two-col">
          <div class="field"><label>Difficulty</label>
            <select name="difficulty">
              <option value="easy">Easy</option>
              <option value="medium" selected>Medium</option>
              <option value="hard">Hard</option>
            </select></div>
          <div class="field"><label>Topic tag (required)</label>
            <select name="topic_id">
              <option value="">Choose a topic…</option>
              ${topics.map((t) => `<option value="${esc(t.id)}">${esc(t.name)}</option>`).join('')}
            </select></div>
        </div>

        <div class="two-col">
          <div class="field"><label>Points</label>
            <input type="number" name="points" min="1" max="100" step="1" value="1"></div>
          <div class="field"><label>Explanation (shown after grading)</label>
            <input type="text" name="explanation" placeholder="Why this answer is right…"></div>
        </div>

        <fieldset class="qfieldset">
          <legend>Options — mark the correct answer</legend>
          <div class="opt-list">
            ${[0, 1, 2, 3].map((i) => `
              <label class="opt-row">
                <input type="radio" name="correct" value="${i}"${i === 0 ? ' checked' : ''}
                  aria-label="Mark option ${i + 1} correct">
                <input type="text" name="opt" placeholder="Option ${i + 1}">
              </label>`).join('')}
          </div>
        </fieldset>

        <div class="row gap" style="justify-content:space-between;margin-top:14px">
          <span class="sm bad" data-err></span>
          <button type="submit" class="btn primary sm">Add question</button>
        </div>
      </form>
    </div>`;
}

function aiCard(topics, subjects, aiOk, test) {
  if (!aiOk) {
    return `
      <div class="card">
        <div class="card-head"><h3>Generate with AI</h3></div>
        ${ui.note('AI drafting is unavailable — no model is connected to the portal ' +
          'right now. You can still add every question by hand.', 'warn')}
      </div>`;
  }
  return `
    <div class="card">
      <div class="card-head"><h3>Generate with AI</h3><span class="tag mute">Draft queue</span></div>
      <p class="sm muted" style="margin-top:0">Drafts land in a review queue first —
        nothing generated here reaches a trainee until you publish it.</p>
      <form data-aiform novalidate>
        <div class="two-col">
          <div class="field"><label>Subject</label>
            <select name="subject_id">
              ${test.subject_id ? '' : '<option value="">Choose a subject…</option>'}
              ${(subjects || []).map((s) => `<option value="${esc(s.id)}"${
                s.id === test.subject_id ? ' selected' : ''}>${esc(s.name)}</option>`).join('')}
            </select></div>
          <div class="field"><label>Topic focus</label>
            <select name="topic_id">
              <option value="">All topics</option>
              ${topics.map((t) => `<option value="${esc(t.id)}">${esc(t.name)}</option>`).join('')}
            </select></div>
        </div>
        <div class="two-col">
          <div class="field"><label>How many</label>
            <input type="number" name="count" min="1" max="40" value="8"></div>
          <div class="field"><label>Difficulty</label>
            <select name="difficulty">
              <option value="easy">Easy</option>
              <option value="medium" selected>Medium</option>
              <option value="hard">Hard</option>
            </select></div>
        </div>
        <div class="field"><label>Extra context (optional)</label>
          <textarea name="context" rows="2" placeholder="Focus on the practical steps…"></textarea></div>
        <div class="row gap" style="justify-content:space-between">
          <span class="sm bad" data-err></span>
          <button type="submit" class="btn primary sm">Generate drafts</button>
        </div>
      </form>
      <div data-airesult class="mt"></div>
    </div>`;
}

function mineInner(questions, tnames) {
  const head = `<div class="card-head"><h3>On this paper</h3>
    <span class="sm muted">${questions.length} question${questions.length === 1 ? '' : 's'}</span></div>`;
  if (!questions.length) {
    return head + '<div class="empty-state">Nothing here yet — your first question ' +
      'will appear in this list.</div>';
  }
  return head + `<div>${questions.map((q, i) => {
    const correct = orderedOptions(q).find((o) => o.is_correct);
    return `
      <div class="ql-item">
        <span class="q-n">${i + 1}</span>
        <div class="ql-t">${esc(q.text)}
          <small>${diffTag(q.difficulty)} ${
            q.topic_id
              ? `<span class="tag info">${esc(tnames[q.topic_id] || 'Tagged')}</span>`
              : '<span class="tag warn">No topic</span>'} ${
            correct ? 'Answer: ' + esc(correct.text) : 'Answer: not set'}</small>
        </div>
        <button type="button" class="btn ghost sm" data-del-q="${esc(q.id)}">Remove</button>
      </div>`;
  }).join('')}</div>`;
}

// ─── /drafts — the AI draft queue ───────────────────────────────────────────

export async function drafts(root, ctx) {
  const offs = [];
  let aiOk = true;
  try {
    aiOk = aiEnabled(await api('/v1/ai/status'));
  } catch (_) { aiOk = true; }

  root.innerHTML = ui.head({
    title: 'AI draft queue',
    sub: 'Drafts never go live on their own — read them, fix the wording, then publish ' +
      'them into a test you own.',
    actions: aiOk
      ? '<a class="btn ghost sm" href="#/tests">Generate more</a>'
      : '',
  })
    + (aiOk ? '' : ui.note(
        'AI drafting is unavailable — no model is connected right now. Existing ' +
        'drafts can still be edited, discarded and published.', 'warn'))
    + `<div class="seg" data-kind-seg>
         <button type="button" class="seg-btn${draftFilters.kind === '' ? ' active' : ''}"
           data-dkind="">All</button>
         <button type="button" class="seg-btn${draftFilters.kind === 'QUESTIONNAIRE' ? ' active' : ''}"
           data-dkind="QUESTIONNAIRE">Questionnaires</button>
         <button type="button" class="seg-btn${draftFilters.kind === 'ASSESSMENT' ? ' active' : ''}"
           data-dkind="ASSESSMENT">Assessments</button>
       </div>
       <div class="toolbar">
         <div class="grow"></div>
         <select name="status" aria-label="Filter by status">
           ${['DRAFT', 'PUBLISHED', 'DISCARDED'].map((s) => `<option value="${s}"${
             draftFilters.status === s ? ' selected' : ''}>${s === 'DRAFT' ? 'Pending review'
               : s.charAt(0) + s.slice(1).toLowerCase()}</option>`).join('')}
         </select>
       </div>
       <div data-body>${ui.loading('drafts')}</div>`;

  const body = root.querySelector('[data-body]');

  offs.push(ui.click(root, '[data-dkind]', (e, btn) => {
    draftFilters.kind = btn.dataset.dkind;
    root.querySelectorAll('[data-dkind]').forEach((b) =>
      b.classList.toggle('active', b.dataset.dkind === draftFilters.kind));
    loadDrafts(body);
  }));
  offs.push(ui.on(root, '.toolbar [name=status]', 'change', (e) => {
    draftFilters.status = e.target.value;
    loadDrafts(body);
  }));
  offs.push(ui.click(root, '[data-retry]', (e) => { e.preventDefault(); loadDrafts(body); }));

  offs.push(ui.click(root, '[data-bulk]', async (e, btn) => {
    const ok = await confirmAction('Publish every pending draft?',
      'All drafts of the chosen type move into the test you pick next. Published ' +
      'and discarded drafts are untouched.', 'Publish all');
    if (!ok) return;
    const targets = await publishTargets();
    openPublishModal(null, targets, () => loadDrafts(body));
  }));

  offs.push(ui.click(root, '[data-pub]', async (e, btn) => {
    const targets = await publishTargets();
    openPublishModal(btn.dataset.pub, targets, () => loadDrafts(body));
  }));

  offs.push(ui.click(root, '[data-draft-edit]', async (e, btn) => {
    const subjects = await loadSubjects();
    let d = null;
    try {
      const res = await api(`/v1/ai/drafts/${btn.dataset.draftEdit}`);
      d = ui.data(res);
    } catch (err) { toast(err.message, 'warn'); return; }
    if (!d) return;
    openDraftEditor(d, subjects, () => loadDrafts(body));
  }));

  offs.push(ui.click(root, '[data-draft-del]', async (e, btn) => {
    const ok = await confirmAction('Discard this draft?',
      'It is removed from the queue for good.', 'Discard');
    if (!ok) return;
    try {
      await api(`/v1/ai/drafts/${btn.dataset.draftDel}`, { method: 'DELETE' });
      toast('Draft discarded.');
      await loadDrafts(body);
    } catch (err) { toast(err.message, 'warn'); }
  }));

  loadDrafts(body);

  return { destroy() { offs.forEach((o) => o()); } };
}

async function loadDrafts(target) {
  target.innerHTML = ui.loading('drafts');
  try {
    const params = new URLSearchParams();
    if (draftFilters.kind) params.set('kind', draftFilters.kind);
    params.set('status', draftFilters.status);
    params.set('limit', '100');

    const res = await api('/v1/ai/drafts?' + params.toString());
    const rows = ui.data(res) || [];
    if (!rows.length) {
      target.innerHTML = draftFilters.status === 'DRAFT'
        ? ui.blank({
            title: 'The queue is empty',
            body: 'Generate questions from the authoring screen of any test and they ' +
              'will land here for review.',
            action: 'Back to tests',
            actionHref: '#/tests',
          })
        : ui.blank({
            title: 'No drafts match',
            body: 'Try another status or look at the whole queue.',
            action: 'Clear filters',
            actionHref: '#/drafts',
          });
      return;
    }
    const bulk = draftFilters.status === 'DRAFT'
      ? `<div class="row gap mb" style="justify-content:flex-end">
           <button type="button" class="btn primary sm" data-bulk>Publish all to…</button>
         </div>` : '';
    target.innerHTML = bulk
      + `<div class="stack">${rows.map(draftCard).join('')}</div>`
      + `<p class="muted sm center mt">${rows.length} draft${
        rows.length === 1 ? '' : 's'} shown</p>`;
  } catch (err) {
    target.innerHTML = ui.errorBlock(err.message);
  }
}

function draftOptions(d) {
  const raw = d.choices || [];
  if (raw.length && typeof raw[0] === 'object') {
    return raw.map((c) => ({ text: String((c && c.text) || ''), correct: !!(c && c.is_correct) }));
  }
  const ci = Number(d.correct_index) || 0;
  return raw.map((c, i) => ({ text: String(c), correct: i === ci }));
}

function draftCard(d) {
  const opts = draftOptions(d);
  const target = d.target_type === 'ASSESSMENT' ? 'Assessment' : 'Questionnaire';
  return `
    <div class="card draft">
      <div class="card-head">
        <h3>${esc(target)} draft</h3>
        <span class="grow"></span>
        ${diffTag(d.difficulty)}
        ${d.topic_name
          ? `<span class="tag info">${esc(d.topic_name)}</span>`
          : '<span class="tag warn">No topic</span>'}
        ${ui.tag(d.status)}
      </div>
      <p class="draft-q">${esc(d.text)}</p>
      <ul class="q-opts">
        ${opts.map((o, i) => `<li class="q-opt${o.correct ? ' ok' : ''}">
          <span class="q-mark">${o.correct ? iconSvg('check') : ''}</span>
          <span>${esc(o.text)}</span>
          ${o.correct ? '<span class="tag ok">Correct</span>' : ''}
        </li>`).join('')}
      </ul>
      ${d.explanation ? `<p class="q-why">Explanation: ${esc(d.explanation)}</p>` : ''}
      <div class="card-foot">
        <span class="sm dim">drafted ${esc(ui.relTime(d.created_at))}</span>
        <span class="grow"></span>
        <button type="button" class="btn ghost sm" data-draft-edit="${esc(d.id)}">Edit</button>
        <button type="button" class="btn ghost sm" data-draft-del="${esc(d.id)}">Discard</button>
        <button type="button" class="btn primary sm" data-pub="${esc(d.id)}">Publish to…</button>
      </div>
    </div>`;
}

/** Tests the signed-in author may still add questions to. */
async function publishTargets() {
  const ok = (t) => t.status === 'DRAFT' || t.status === 'PENDING_RELEASE';
  try {
    const [qRes, aRes] = await Promise.all([
      api('/v1/questionnaires?mine=true&limit=100'),
      api('/v1/assessments?mine=true&limit=100'),
    ]);
    return {
      q: (ui.data(qRes) || []).filter(ok),
      a: (ui.data(aRes) || []).filter(ok),
    };
  } catch (_) {
    return { q: [], a: [] };
  }
}

function openPublishModal(draftId, targets, onDone) {
  const group = (rows, label) => rows.length
    ? `<optgroup label="${esc(label)}">${rows
        .map((t) => `<option value="${esc(t.id)}">${esc(t.title)}</option>`)
        .join('')}</optgroup>` : '';
  const options = group(targets.q, 'Questionnaires') + group(targets.a, 'Assessments');
  if (!options) {
    toast('You have no editable test yet — create a draft test first.', 'warn');
    return;
  }

  openAppModal(`
    <h3 class="modal-title">${draftId ? 'Publish this draft' : 'Publish every draft'}</h3>
    <p class="modal-sub">${draftId
      ? 'Choose the test this question belongs to.'
      : 'Every pending draft of the chosen type moves into the test you pick.'}</p>
    <form data-pub-form>
      <div class="field"><label>Test</label>
        <select name="target_id">
          <option value="">Choose a test…</option>
          ${options}
        </select></div>
      <p class="sm muted">Draft and submitted tests only — released tests cannot take
        new questions until Supreme re-opens them.</p>
      <div class="row gap" style="justify-content:space-between">
        <span class="sm bad" data-err></span>
        <span class="row gap">
          <button type="button" class="btn ghost sm" data-pub-cancel>Cancel</button>
          <button type="submit" class="btn primary sm">Publish</button>
        </span>
      </div>
    </form>`);

  const host = document.getElementById('app-modal-body');
  const form = host ? host.querySelector('[data-pub-form]') : null;
  if (!form) return;
  form.querySelector('[data-pub-cancel]')
    .addEventListener('click', () => closeAppModal());
  form.addEventListener('submit', (e) => {
    e.preventDefault();
    const targetId = form.querySelector('[name=target_id]').value;
    if (!targetId) { ui.formError(form, 'Choose where these questions go.'); return; }
    ui.formError(form, '');
    const btn = form.querySelector('[type=submit]');
    ui.busy(btn, 'Publishing…', async () => {
      try {
        const res = draftId
          ? await api(`/v1/ai/drafts/${draftId}/publish`, {
              method: 'POST', body: JSON.stringify({ target_id: targetId }),
            })
          : await api('/v1/ai/drafts/bulk-publish', {
              method: 'POST', body: JSON.stringify({ target_id: targetId }),
            });
        const out = ui.data(res) || {};
        const n = Number(out.published) || 0;
        const skipped = out.skipped || [];
        if (n && skipped.length) {
          toast(`${n} published, ${skipped.length} skipped — ${
            (skipped[0] && skipped[0].reason) || 'check the queue'}.`, 'warn');
        } else if (n) {
          toast(`${n} question${n === 1 ? '' : 's'} published.`);
        } else {
          toast(`Nothing published — ${(skipped[0] && skipped[0].reason)
            || 'no pending drafts'}.`, 'warn');
        }
        closeAppModal();
        onDone();
      } catch (err) { ui.formError(form, err.message); }
    });
  });
}

function openDraftEditor(d, subjects, onSaved) {
  const opts = draftOptions(d);
  const rows = [0, 1, 2, 3].map((i) => (opts[i] ? opts[i].text : ''));
  const ci = Math.min(Math.max(Number(d.correct_index) || 0, 0), rows.length - 1);
  const topicGroups = (subjects || []).map((s) => {
    const list = s.topics || [];
    if (!list.length) return '';
    return `<optgroup label="${esc(s.name)}">${list
      .map((t) => `<option value="${esc(t.id)}"${t.id === d.topic_id ? ' selected' : ''}>${
        esc(t.name)}</option>`).join('')}</optgroup>`;
  }).join('');

  openAppModal(`
    <h3 class="modal-title">Edit draft</h3>
    <p class="modal-sub">Fix the wording, the answer or the topic — publish it when it reads well.</p>
    <form data-draft-form novalidate>
      <div class="field"><label>Question</label>
        <textarea name="text" rows="3">${esc(d.text)}</textarea></div>

      <div class="field"><label>Options</label>
        <div class="opt-list">
          ${rows.map((t, i) => `<label class="opt-row">
            <input type="text" name="opt" value="${esc(t)}" placeholder="Option ${i + 1}">
          </label>`).join('')}
        </div></div>

      <div class="two-col">
        <div class="field"><label>Correct answer</label>
          <select name="correct_index">${rows.map((t, i) => `<option value="${i}"${
            i === ci ? ' selected' : ''}>Option ${i + 1}${t ? ' — ' + esc(t) : ''}</option>`
          ).join('')}</select></div>
        <div class="field"><label>Difficulty</label>
          <select name="difficulty">${['easy', 'medium', 'hard'].map((v) => `<option value="${
            v}"${v === (d.difficulty || 'medium') ? ' selected' : ''}>${
            v.charAt(0).toUpperCase() + v.slice(1)}</option>`).join('')}</select></div>
      </div>

      <div class="field"><label>Topic tag</label>
        <select name="topic_id">
          <option value="">No topic…</option>
          ${topicGroups}
        </select></div>

      <div class="field"><label>Explanation (optional)</label>
        <textarea name="explanation" rows="2">${esc(d.explanation || '')}</textarea></div>

      <div class="row gap" style="justify-content:space-between">
        <span class="sm bad" data-err></span>
        <span class="row gap">
          <button type="button" class="btn ghost sm" data-draft-cancel>Cancel</button>
          <button type="submit" class="btn primary sm">Save draft</button>
        </span>
      </div>
    </form>`);

  const host = document.getElementById('app-modal-body');
  const form = host ? host.querySelector('[data-draft-form]') : null;
  if (!form) return;

  const optInputs = () => Array.from(form.querySelectorAll('[name=opt]'));
  const select = form.querySelector('[name=correct_index]');

  // Keep the "correct answer" labels in step with what is typed.
  ui.on(form, '[name=opt]', 'input', () => {
    Array.from(select.options).forEach((op, i) => {
      const v = (optInputs()[i] || {}).value || '';
      op.textContent = v.trim() ? `Option ${i + 1} — ${v.trim()}` : `Option ${i + 1}`;
    });
  });

  form.querySelector('[data-draft-cancel]')
    .addEventListener('click', () => closeAppModal());

  form.addEventListener('submit', (e) => {
    e.preventDefault();
    const text = form.querySelector('[name=text]').value.trim();
    const values = optInputs().map((i) => i.value.trim());
    const correctAt = Number(select.value) || 0;
    const kept = values.map((t, i) => ({ t, i })).filter((o) => o.t);

    if (text.length < 3) {
      ui.formError(form, 'The question needs at least 3 characters.');
      return;
    }
    if (kept.length < 2) { ui.formError(form, 'Keep at least two options.'); return; }
    if (!values[correctAt]) {
      ui.formError(form, 'The option marked correct is empty — fill it in or pick another.');
      return;
    }
    ui.formError(form, '');

    const btn = form.querySelector('[type=submit]');
    ui.busy(btn, 'Saving…', async () => {
      try {
        const res = await api(`/v1/ai/drafts/${d.id}`, {
          method: 'PUT',
          body: JSON.stringify({
            text,
            options: kept.map((o) => o.t),
            correct_index: kept.findIndex((o) => o.i === correctAt),
            explanation: form.querySelector('[name=explanation]').value.trim(),
            difficulty: form.querySelector('[name=difficulty]').value,
            topic_id: form.querySelector('[name=topic_id]').value,
          }),
        });
        if (!ui.data(res)) throw new Error('The draft could not be saved.');
        closeAppModal();
        toast('Draft updated.');
        onSaved();
      } catch (err) { ui.formError(form, err.message); }
    });
  });
}
